// Generated by the data pipeline and loaded read-only by the app.
export type SpectralClass =
  'O' | 'B' | 'A' | 'F' | 'G' | 'K' | 'M' | 'L' | 'T' | 'Y' | 'D' | 'unknown';

export type Position = readonly [x: number, y: number, z: number];

export interface StarNames {
  readonly proper?: string;
  readonly bayer?: string;
  readonly flamsteed?: string;
  readonly gliese?: string;
  readonly hd?: string;
  readonly hip?: string;
  readonly hr?: string;
  readonly other: readonly string[];
}

export interface Spectral {
  readonly raw?: string;
  readonly cls: SpectralClass;
  readonly sub?: number;
  readonly lumClass?: string;
}

export interface Star {
  readonly id: string; // stable: 'hyg:<id>', 'ovr:<slug>' or 'exo:<hostname slug>'
  readonly systemId: string;
  readonly names: StarNames;
  readonly displayName: string; // best available: proper > bayer > flamsteed > gliese > HD > HIP
  readonly pos: Position; // galactic, light-years, Sun at origin
  readonly distLy: number;
  readonly mag?: number;
  readonly absMag?: number;
  readonly spectral: Spectral;
  readonly tempK?: number;
  readonly lumSolar?: number; // bolometric
  readonly massSolar?: number;
  readonly massEstimated: boolean;
  readonly hzAu?: readonly [inner: number, outer: number];
  readonly colorHex: string;
  readonly isPrimary: boolean;
  readonly planetIds: readonly string[];
  readonly source: 'hyg' | 'exoplanet-archive' | 'override';
}

export interface StarMotion {
  readonly velLyPerYear: Position; // galactic
  readonly radialKnown: boolean; // without a radial velocity, this is motion across the sky only
}

export interface StarSystem {
  readonly id: string;
  readonly name: string; // e.g. 'Alpha Centauri'
  readonly starIds: readonly string[]; // primary first
  readonly pos: Position; // primary's position
  readonly distLy: number;
  readonly planetCount: number;
  readonly motion?: StarMotion; // absent where no source gives one
}

export interface Planet {
  readonly id: string;
  readonly name: string;
  readonly letter: string;
  readonly hostStarId: string;
  readonly periodDays?: number;
  readonly semiMajorAu?: number;
  readonly eccentricity?: number;
  readonly radiusEarth?: number;
  readonly massEarth?: number;
  readonly eqTempK?: number;
  readonly insolEarth?: number;
  readonly discoveryMethod: string;
  readonly discoveryYear?: number; // the Sun's oldest planets have none
  readonly inHabitableZone?: boolean; // derived from host hzAu
}

export interface Probe {
  readonly id: string;
  readonly name: string;
  readonly pos: Position; // galactic, light-years, Sun at origin, at the reference epoch
  readonly velLyPerYear: Position; // galactic
  readonly speedKmS: number;
}

export interface Pulsar {
  readonly id: string; // B name, e.g. 'B0531+21'
  readonly jName: string;
  readonly direction: Position; // galactic unit vector, from catalogue RA and Dec
  readonly plaquePeriodS: number; // as engraved in 1972, which later measurements refine
}

export interface ProbeData {
  readonly epochYear: number;
  readonly probes: readonly Probe[];
  readonly pulsars: readonly Pulsar[];
}

export interface CatalogueSource {
  readonly name: string;
  readonly version: string;
  readonly url: string;
  readonly licence: string;
  readonly sha256?: string;
  readonly fetchedAt: string;
}

export interface UnmatchedHost {
  readonly hostname: string;
  readonly distLy: number;
}

export interface CatalogueMeta {
  readonly buildDate: string;
  readonly radiusLy: number;
  readonly sources: readonly CatalogueSource[];
  readonly counts: {
    readonly stars: number;
    readonly systems: number;
    readonly planets: number;
  };
  readonly unmatchedHosts: readonly UnmatchedHost[]; // archive hosts added as new star records
  readonly attribution: string;
  readonly idMap: Readonly<Record<string, string>>; // retired star/system ID -> current ID
}
